// Собираем человеческое сообщение из того, что отдаёт Error Trigger.
// Читать его будет человек в Telegram, а не машина — поэтому без JSON и стеков.
const j = $input.first().json || {};
const wf = (j.workflow && j.workflow.name) || 'неизвестный воркфлоу';
const ex = j.execution || {};
const err = ex.error || j.error || {};

const node = err.node && err.node.name ? err.node.name : '—';
const msg = String(err.message || 'без описания').slice(0, 300);
const url = ex.url || '';
const ts = new Date().toISOString().slice(0, 16).replace('T', ' ');

const text = `\u{1F534} Nordwaren VoiceDesk — сбой, клиент остался без ответа\n${ts}\n\nВоркфлоу: ${wf}\nУпало на ноде: ${node}\nПричина: ${msg}` +
  (url ? `\n\nПрогон: ${url}` : '') +
  `\n\nЧаще всего это значит, что Mac выключен/уснул или LM Studio не поднят.`;

return [{ json: { text }, pairedItem: { item: 0 } }];

// Три проверки → один вердикт.
// Проверки сделаны отдельными HTTP-нодами, а не кодом: в Code-ноде этого n8n
// $helpers НЕДОСТУПЕН («is not defined», прогон 987) — и все три вызова падали в catch,
// а сторож рапортовал «лежат все три», хотя лежал один.
// Ложная тревога хуже отсутствия тревоги: на неё перестают реагировать.

const probe = (label, node, check) => {
  let j;
  try { j = $(node).first().json; } catch (e) { return `${label}: проверка не выполнилась`; }
  if (!j || j.error !== undefined) return `${label}: не отвечает`;
  const why = check ? check(j) : null;
  return why ? `${label}: ${why}` : null;
};

const down = [
  probe('Голос (Piper + whisper)', '2a. Проверка — голос',
    (j) => (j.whisper && j.whisper !== 'ok') ? 'синтез жив, РАСПОЗНАВАНИЕ не отвечает' : null),
  probe('Векторная база Qdrant', '2b. Проверка — Qdrant'),
  probe('Модель LM Studio', '2c. Проверка — LM Studio'),
  probe('Postgres (каталог/журнал)', '2e. Проверка — Postgres'),
].filter(Boolean);

const ts = new Date().toISOString().slice(0, 16).replace('T', ' ');

// Дедупликация (запрос Dennis 15.08): без неё сторож шлёт одно и то же предупреждение каждые
// 10 минут, пока проблема не устранена — от повторов перестают реагировать. Алерт
// теперь только на СМЕНУ набора сломанных сервисов (новая поломка, изменился состав сломанного,
// или всё отлегло) — не на каждом тике. Состояние — в staticData, переживает тики, не переживает перезапуск n8n.
const store = $getWorkflowStaticData('global');
const prevDown = store.watchdogPrevDown || [];
const downKey = down.slice().sort().join('|');
const prevKey = prevDown.slice().sort().join('|');
const changed = downKey !== prevKey;
store.watchdogPrevDown = down;

const shouldAlert = down.length > 0 && changed;

const text = shouldAlert
  ? `⚠️ Nordwaren VoiceDesk — локальный стек неисправен\n${ts}\n\nНе отвечают:\n• ${down.join('\n• ')}\n\nАссистент сейчас либо молчит, либо отвечает клиентам неверно.\nПроверьте: включён ли Mac, есть ли Tailscale, поднят ли LM Studio.\n\n(Повторно не напомним, пока состав неисправностей не изменится.)`
  : '';

return [{ json: { alert: shouldAlert, down, text }, pairedItem: { item: 0 } }];
